"use strict";function formatHeader(t){return t.replace(/([A-Z])/g," $1").replace(/_/g," ").replace(/\w\S*/g,r=>r.charAt(0).toUpperCase()+r.substr(1).toLowerCase()).trim()}function formatList(t,r){if(!t)return"";const e=t.split(r).filter(n=>n.trim());return e.length===0?"":`<ul class="list-disc pl-4">
        ${e.map(n=>`<li>${n.trim()}</li>`).join("")}
    </ul>`}function truncateUrl(t,r=40){return t.length>r?t.substring(0,r)+"...":t}function formatUrls(t){if(!t)return"";const r=t.split(", ").filter(Boolean);return r.length===0?"":r.map(e=>`<li>
            <a href="${e}"
               title="${e}"
               target="_blank" 
               rel="noopener noreferrer"
               class="url-link hover:text-blue-600">
                ${truncateUrl(e)}
            </a>
        </li>`).join("")}const DEFAULT_FIELD_FORMAT=t=>t||"";function createFieldConfig(t){const r={};return Object.entries(t).forEach(([e,n])=>{r[e]=typeof n=="boolean"?{include:n,format:DEFAULT_FIELD_FORMAT}:{include:n.include!==!1,format:n.format||DEFAULT_FIELD_FORMAT}}),r}
